// 支援 Webhook（$json.body）與 Demo 路徑（$json 直接帶 incident_id）
const id = $json.body?.incident_id || $json.incident_id || 'INC-2026-0703';
return [{ json: { incident_id: id } }];

// 把事件資料組成 AI 易讀的文字（時間軸逐行列出）
const inc = $json;
const timeline = (inc.timeline || []).map(t => `- ${t.time}: ${t.event}`).join('\n');
const actions = (inc.actions_taken || []).map((a, i) => `${i + 1}. ${a}`).join('\n');
const durationMin = Math.round((new Date(inc.resolved_at) - new Date(inc.started_at)) / 60000);
const context = [
  `事件編號：${inc.incident_id}`,
  `標題：${inc.title}`,
  `嚴重度：${inc.severity}`,
  `持續時間：${durationMin} 分鐘（${inc.started_at} → ${inc.resolved_at}）`,
  `受影響服務：${(inc.affected_services || []).join('、')}`,
  `影響描述：${inc.impact}`,
  '',
  '時間軸：',
  timeline,
  '',
  '已執行的處置動作：',
  actions
].join('\n');
return [{ json: { incident_id: inc.incident_id, context } }];

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '(生成失敗)';
const pir = text.replace(/```(markdown)?\n?|```/g, '').trim();
return [{ json: {
  incident_id: $('組事件上下文').item.json.incident_id,
  generated_at: new Date().toISOString(),
  pir_markdown: pir
} }];
// 延伸：接 HTTP Request 把 PIR 寫回事件系統，或接 Email 寄給關係人
